"""Add synchronized exception cases and complete resolution snapshots."""
from alembic import op

revision = '0010_proc_exceptions'
down_revision = '0009_proc_plans'
branch_labels = None
depends_on = None

SQL = "-- Exception projections preserve complete source facts, including both resolution formats.\nALTER TABLE public.records ADD CONSTRAINT uq_records_tenant_id UNIQUE(tenant,id);\nCREATE TABLE public.proc_exceptions (\n    tenant varchar(64) NOT NULL,\n    id varchar(64) NOT NULL,\n    source_revision integer NOT NULL CHECK(source_revision>=1),\n    resource_id varchar(64) NOT NULL CHECK(length(resource_id)>0),\n    category varchar(80) NOT NULL CHECK(length(category)>=3),\n    detail text NOT NULL CHECK(length(detail)>=5 AND length(detail)<=2000),\n    owner_id varchar(64) NOT NULL CHECK(length(owner_id)>0),\n    due_date date NOT NULL CHECK(isfinite(due_date)),\n    status text NOT NULL CHECK(status IN ('open','resolved')),\n    resolution text,\n    evidence_id varchar(64),\n    resolution_reason text,\n    resolution_evidence varchar(64),\n    resolved_by varchar(64),\n    resolved_at timestamptz CHECK(isfinite(resolved_at)),\n    matched_invoice_revision integer CHECK(matched_invoice_revision>=1),\n    source_snapshot jsonb NOT NULL CHECK(jsonb_typeof(source_snapshot)='object'),\n    PRIMARY KEY(tenant,id),\n    FOREIGN KEY(tenant,id) REFERENCES public.records(tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    FOREIGN KEY(tenant,resource_id) REFERENCES public.records(tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    FOREIGN KEY(tenant,evidence_id) REFERENCES public.records(tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    FOREIGN KEY(tenant,resolution_evidence) REFERENCES public.records(tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    CHECK(status<>'resolved' OR\n          (resolved_by IS NOT NULL AND length(resolved_by)>0 AND\n           ((resolution IS NOT NULL AND length(resolution)>=5 AND evidence_id IS NOT NULL) OR\n            (resolution_reason IS NOT NULL AND length(resolution_reason)>=5 AND resolution_evidence IS NOT NULL))))\n);\nCREATE INDEX ix_proc_exceptions_resource ON public.proc_exceptions(tenant,resource_id,status);\nCREATE INDEX ix_proc_exceptions_owner_due ON public.proc_exceptions(tenant,owner_id,status,due_date);\nALTER TABLE public.proc_exceptions ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.proc_exceptions FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_scope ON public.proc_exceptions TO supplypilot_app\n    USING(tenant=NULLIF(current_setting('supplypilot.tenant',true),''))\n    WITH CHECK(tenant=NULLIF(current_setting('supplypilot.tenant',true),''));\nCREATE POLICY migration_owner ON public.proc_exceptions TO supplypilot_migrator USING(true) WITH CHECK(true);\nREVOKE ALL ON TABLE public.proc_exceptions FROM PUBLIC,supplypilot_app;\nGRANT SELECT ON TABLE public.proc_exceptions TO supplypilot_app;\n\nCREATE FUNCTION public.sync_procurement_exception()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp\nAS $$ DECLARE d jsonb; key text;\nBEGIN\n    IF TG_OP='UPDATE' AND (OLD.kind='exception' OR NEW.kind='exception') AND\n       (OLD.tenant,OLD.id,OLD.kind) IS DISTINCT FROM (NEW.tenant,NEW.id,NEW.kind) THEN\n        RAISE EXCEPTION 'Exception identity, tenant and kind are immutable' USING ERRCODE='23514';\n    END IF;\n    IF TG_OP='DELETE' THEN\n        IF OLD.kind='exception' THEN DELETE FROM public.proc_exceptions WHERE tenant=OLD.tenant AND id=OLD.id; END IF;\n        RETURN OLD;\n    END IF;\n    IF NEW.kind<>'exception' THEN RETURN NEW; END IF;\n    d:=NEW.data::jsonb;\n    FOREACH key IN ARRAY ARRAY['resource_id','category','detail','owner','due_date','status'] LOOP\n        IF jsonb_typeof(d->key) IS DISTINCT FROM 'string' THEN\n            RAISE EXCEPTION 'Exception fields must be strings' USING ERRCODE='23514';\n        END IF;\n    END LOOP;\n    FOREACH key IN ARRAY ARRAY['resolution','resolution_reason','evidence_id','resolution_evidence','resolved_by','resolved_at'] LOOP\n        IF d ? key AND d->key<>'null'::jsonb AND jsonb_typeof(d->key)<>'string' THEN\n            RAISE EXCEPTION 'Exception resolution fields must be strings' USING ERRCODE='23514';\n        END IF;\n    END LOOP;\n    IF d ? 'matched_invoice_revision' AND d->'matched_invoice_revision'<>'null'::jsonb AND\n       (jsonb_typeof(d->'matched_invoice_revision') IS DISTINCT FROM 'number' OR\n        (d->>'matched_invoice_revision')::numeric<>trunc((d->>'matched_invoice_revision')::numeric)) THEN\n        RAISE EXCEPTION 'Matched invoice revision must be an integer' USING ERRCODE='23514';\n    END IF;\n    INSERT INTO public.proc_exceptions VALUES(NEW.tenant,NEW.id,NEW.revision,d->>'resource_id',\n        d->>'category',d->>'detail',d->>'owner',(d->>'due_date')::date,d->>'status',\n        d->>'resolution',d->>'evidence_id',d->>'resolution_reason',d->>'resolution_evidence',d->>'resolved_by',\n        (d->>'resolved_at')::timestamptz,(d->>'matched_invoice_revision')::integer,d)\n    ON CONFLICT(tenant,id) DO UPDATE SET source_revision=EXCLUDED.source_revision,\n        resource_id=EXCLUDED.resource_id,category=EXCLUDED.category,detail=EXCLUDED.detail,\n        owner_id=EXCLUDED.owner_id,due_date=EXCLUDED.due_date,status=EXCLUDED.status,\n        resolution=EXCLUDED.resolution,evidence_id=EXCLUDED.evidence_id,\n        resolution_reason=EXCLUDED.resolution_reason,resolution_evidence=EXCLUDED.resolution_evidence,\n        resolved_by=EXCLUDED.resolved_by,resolved_at=EXCLUDED.resolved_at,\n        matched_invoice_revision=EXCLUDED.matched_invoice_revision,source_snapshot=EXCLUDED.source_snapshot;\n    RETURN NEW;\nEND $$;\nREVOKE ALL ON FUNCTION public.sync_procurement_exception() FROM PUBLIC,supplypilot_app;\nCREATE TRIGGER records_exception_sync AFTER INSERT OR UPDATE OR DELETE ON public.records\nFOR EACH ROW EXECUTE FUNCTION public.sync_procurement_exception();\nUPDATE public.records SET data=data WHERE kind='exception';\n"


def upgrade():
    op.execute(SQL)


